definition.script:
pipeline {
    agent any

    stages {

        stage('Import raw data and build dataset databases') {
            steps {
                build job: 'Curation - RECOVER Pediatric Import raw data', parameters: [
                                        string(name: 'VERSION', value: params.VERSION),
                                         string(name: 'INPUT_S3_FOLDER_URI', value: params.INPUT_S3_FOLDER_URI),
                                         string(name: 'manifest_file_uri', value: params.manifest_file_uri),
                                         string(name: 'sstr_file_uri', value: params.sstr_file_uri)
                ]
            }
        }
        stage('Curate files using psql scripts') {
            steps {
                build job: 'Curation - Recover Pediatric Curate Files',
                    parameters: [
                         string(name: 'VERSION', value: params.VERSION)
                    ]
            }
        }
        stage('Export curated data to s3') {
            steps {
                build job: 'Curation - Recover Pediatric Export Dataset',
                    parameters: [
                         string(name: 'VERSION', value: params.VERSION),
                         string(name: 'STUDY_ABV', value: params.STUDY_ABV)
                    ]
                build job: 'Curation - Recover Pediatric Export Metadata',
                    parameters: [
                         string(name: 'VERSION', value: params.VERSION),
                         string(name: 'STUDY_ABV', value: params.STUDY_ABV)
                    ]    
            }
        }
    }
}
